//
// .NET spike: scan one image with the three profiles through C# bindings generated by
// uniffi-bindgen-cs, in process, and write one JSON report per profile for
// `scripts/destination-acceptance.py reports` to judge.
//
//   QrscanSpike IMAGE OUT_DIR
//
// Each report file is the text the engine returned, unchanged. `facts.json` records what the
// spike measured: the time of each scan, what a file that is not an image raises, and the host.
// This program judges nothing.
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text.Json;
using QRCodeAI.Scanner.Generated;

if (args.Length != 2)
{
    Console.Error.WriteLine("usage: QrscanSpike IMAGE OUT_DIR");
    return 2;
}
var image = File.ReadAllBytes(args[0]);
Directory.CreateDirectory(args[1]);

// The library answers before any scan: this is the call that fails when the generated C# and the
// native library do not come from the same UniFFI line.
var capabilities = NativeScanner.Capabilities();
using var described = JsonDocument.Parse(capabilities);
Console.WriteLine("engine " + described.RootElement.GetProperty("versions").GetRawText());

var milliseconds = new Dictionary<string, double>();
foreach (var profile in new[] { "fast", "frame", "full" })
{
    // A budget of 0 is unbounded: the result does not depend on how busy the host is.
    var clock = Stopwatch.StartNew();
    string report = NativeScanner.Scan(image, profile, null, null, 0UL, null, null, null, null, null);
    clock.Stop();
    milliseconds[profile] = Math.Round(clock.Elapsed.TotalMilliseconds, 1);
    File.WriteAllText(Path.Combine(args[1], profile + ".json"), report);
    using var parsed = JsonDocument.Parse(report);
    var found = parsed.RootElement.GetProperty("detections").EnumerateArray()
        .Select(row => row.GetProperty("symbology").GetString() + ":" + row.GetProperty("content").GetProperty("text").GetString());
    Console.WriteLine($"{profile} {string.Join(" ", found)} ({milliseconds[profile]} ms)");
}

// A file that is not an image must come back as an exception that carries the engine's own code.
string refusalType = "none", refusalMessage = "";
try
{
    NativeScanner.Scan("this is not an image"u8.ToArray(), "frame", null, null, 0UL, null, null, null, null, null);
}
catch (Exception refusal)
{
    refusalType = refusal.GetType().FullName ?? refusal.GetType().Name;
    refusalMessage = refusal.Message;
}
Console.WriteLine($"not an image -> {refusalType}: {refusalMessage}");

var facts = new Dictionary<string, object>
{
    ["capabilities"] = JsonSerializer.Deserialize<JsonElement>(capabilities),
    ["milliseconds"] = milliseconds,
    ["notAnImage"] = new Dictionary<string, string> { ["exception"] = refusalType, ["message"] = refusalMessage },
    ["dotnet"] = RuntimeInformation.FrameworkDescription,
    ["os"] = RuntimeInformation.OSDescription,
    ["architecture"] = RuntimeInformation.ProcessArchitecture.ToString(),
};
File.WriteAllText(Path.Combine(args[1], "facts.json"), JsonSerializer.Serialize(facts, new JsonSerializerOptions { WriteIndented = true }));
return refusalMessage.Contains("QRS-") ? 0 : 1;
